package com.nequard.topology;
import com.nequard.auth.OrganizationAccessService;import com.nequard.network.Device;import com.nequard.network.DeviceRepository;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/topology") public class TopologyController{private final TopologyLinkRepository repo;private final DeviceRepository devices;private final OrganizationAccessService access;public TopologyController(TopologyLinkRepository r,DeviceRepository d,OrganizationAccessService a){repo=r;devices=d;access=a;}@GetMapping("/links")public List<TopologyLink> links(Authentication a){if(access.isSuperAdmin(a))return repo.findAll();Set<UUID> ids=new HashSet<>();for(Device d:devices.findByOrganizationId(access.currentOrganization(a)))ids.add(d.getId());return repo.findAll().stream().filter(x->ids.contains(x.getSourceDeviceId())&&ids.contains(x.getTargetDeviceId())).toList();}@PostMapping("/links")@PreAuthorize("hasAnyRole('SUPER_ADMIN','NETWORK_ADMIN','NETWORK_ENGINEER')")public ResponseEntity<?> create(Authentication a,@RequestBody TopologyLink l){return devices.findById(l.getSourceDeviceId()).filter(s->access.canAccess(a,s.getOrganizationId())).flatMap(s->devices.findById(l.getTargetDeviceId()).filter(t->access.canAccess(a,t.getOrganizationId()))).map(x->ResponseEntity.status(201).body(repo.save(l))).orElse(ResponseEntity.status(403).build());}@DeleteMapping("/links/{id}")@PreAuthorize("hasAnyRole('SUPER_ADMIN','NETWORK_ADMIN','NETWORK_ENGINEER')")public ResponseEntity<Void> delete(Authentication a,@PathVariable UUID id){return repo.findById(id).filter(l->devices.findById(l.getSourceDeviceId()).map(d->access.canAccess(a,d.getOrganizationId())).orElse(false)).map(l->{repo.delete(l);return ResponseEntity.noContent().<Void>build();}).orElse(ResponseEntity.notFound().build());}}